  {"decl": "TwoDegenerateGraphs.neighborsWithin", "line": 8, "plain": "The neighbours of v inside the finite vertex set s, i.e. s ∩ N(v).", "standard_concept": "degree of v in the induced subgraph G[s]", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s has a vertex with at most r neighbours inside s.", "standard_concept": "r-degenerate graph (every nonempty subgraph has a vertex of degree ≤ r)", "matches_standard": "yes", "note": "Using induced subgraphs on finsets is equivalent to using arbitrary subgraphs, since removing edges only lowers degrees."},
  {"decl": "TwoDegenerateGraphs.IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2.", "standard_concept": "2-degenerate", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.DegeneracyConjectureStatement", "line": 20, "plain": "For every r>0 and every bipartite r-degenerate graph H on Fin q, ex(n,H)=O(n^{2−1/r}) as n→∞.", "standard_concept": "Erdős's degeneracy conjecture (3): ex(n,H)=O(n^{2−1/r})", "matches_standard": "yes", "note": "It relies on Mathlib's extremalNumber (max edges of an H-free simple graph on Fin n, with H-free meaning no subgraph copy) and Mathlib's IsBipartite (2-colourable). Both match the paper's ex(n,H) and bipartiteness."}
 ],
 "lean_claims": [
  {"theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q that is connected, bipartite and 2-degenerate. For every proper 2-colouring of H and each colour side, the maximum degree over that side exceeds 2. Moreover there are c, ε > 0 such that for all sufficiently large n, ex(n,H) ≥ c·n^{3/2+ε}."},
  {"theorem": "TwoDegenerateGraphs.not_erdos_146", "line": 43, "plain": "It is not true that for all r>0 and all bipartite r-degenerate H on Fin q, ex(n,H)=O(n^{2−1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Intro / abstract", "plain": "This disproves Erdős's conjecture that every bipartite r-degenerate graph has ex(n,H)=O(n^{2−1/r}), already at r=2."}
 ],
